        jne     .L40                        ; unsigned !=
        jmp     .L38
.L40:
        mov     ax, 1
        jmp     .L39
.L38:
        xor     ax, ax
.L39:
        mov     [isRunning], al             ; narrowed to bool
.L35:
        ret

; ============================================== sub update ====

update:
; ---- drawScore()
        call    drawScore
        ret

; ============================================== sub waitMicros ====

waitMicros:
; ---- _ah = 0x86
        mov     byte [_ah], 134
; ---- _cx = high
        mov     ax, [waitMicros__high]
        mov     [_cx], ax
; ---- _dx = low
        mov     ax, [waitMicros__low]
        mov     [_dx], ax
; ---- int 0x15
        call    int15
        ret

; ============================================== sub doWait ====

doWait:
; ---- sub doWait => waitMicros( 0, frameMicros )
        mov     word [waitMicros__high], 0
        mov     word [waitMicros__low], 33333
        call    waitMicros
        ret

; ============================================== sub render ====

render:
; ---- clearBall()
        call    clearBall
; ---- clearPaddles()
        call    clearPaddles
; ---- drawNet()
        call    drawNet
; ---- drawBall()
        call    drawBall
; ---- drawPaddles()
        call    drawPaddles
        ret

; ============================================== sub tick ====

tick:
; ---- input()
        call    input
; ---- update()
        call    update
; ---- render()
        call    render
; ---- doWait()
        call    doWait
        ret

; ============================================== sub serve ====

serve:
; ---- ballSpeedY = 0
        mov     word [ballSpeedY], 0
; ---- volleyCount = 0
        mov     byte [volleyCount], 0
; ---- if( ballPlayer ){
        mov     al, [ballPlayer]
        test    al, al
        jnz     .L43
        jmp     .L41
.L43:
; ---- ballX = 4
        mov     word [ballX], 4
; ---- ballY = p1Y + 12
        mov     ax, [p1Y]
        add     ax, 12
        mov     [ballY], ax
; ---- ballSpeedX = 3
        mov     word [ballSpeedX], 3
; ---- ballColor = red
        mov     byte [ballColor], 4
        jmp     .L42
.L41:
; ---- ballX = ballXMax - 4
        mov     word [ballX], 292
; ---- ballY = p2Y + 12
        mov     ax, [p2Y]
        add     ax, 12
        mov     [ballY], ax
; ---- ballSpeedX = -3
        mov     word [ballSpeedX], 65533
; ---- ballColor = blue
        mov     byte [ballColor], 6
.L42:
        ret

; ============================================== sub start ====

start:
; ---- seedRandom( ticks() )
        call    ticks
        mov     ax, [ticks__ret]
        mov     [seedRandom__s], ax
        call    seedRandom
; ---- isWinScreen = false
        mov     byte [isWinScreen], 0
; ---- score1 = 0
        mov     byte [score1], 0
; ---- score2 = 0
        mov     byte [score2], 0
; ---- p1Speed = 0
        mov     byte [p1Speed], 0
; ---- p2Speed = 0
        mov     byte [p2Speed], 0
; ---- p1Y = paddleYHome
        mov     word [p1Y], 122
; ---- p2Y = paddleYHome
        mov     word [p2Y], 122
; ---- oP1Y = p1Y
        mov     ax, [p1Y]
        mov     [oP1Y], ax
; ---- oP2Y = p2Y
        mov     ax, [p2Y]
        mov     [oP2Y], ax
; ---- ballPlayer = randomBelow( 2 )
        mov     word [randomBelow__n], 2
        call    randomBelow
        mov     ax, [randomBelow__ret]
        mov     [ballPlayer], al            ; narrowed to u8
; ---- drawBackground()
        call    drawBackground
; ---- drawPlayfield()
        call    drawPlayfield
; ---- serve()
        call    serve
; ---- oBallX = ballX
        mov     ax, [ballX]
        mov     [oBallX], ax
; ---- oBallY = ballY
        mov     ax, [ballY]
        mov     [oBallY], ax
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int15:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x15
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int16:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x16
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

